<template><section class="diary-personal"><header class="diary-personal-head"><div><h2>Mis recordatorios personales</h2><p>Solo tú puedes verlos. No forman parte de la productividad laboral.</p></div><button type="button" class="diary-primary" @click="create">+ Recordatorio personal</button></header><p v-if="error" class="diary-error" role="alert">{{error}}</p><p v-if="limited" class="diary-error">Se muestran los 1000 recordatorios más recientes.</p><label>Mostrar<select v-model="state"><option value="pendiente">Pendientes</option><option value="concluida">Concluidos</option><option value="cancelada">Cancelados</option><option value="">Todos</option></select></label><div class="diary-list"><article v-for="t in visible" :key="t.Id" class="diary-task"><span class="diary-badge">{{t.Estado}}</span><h3>{{t.Titulo}}</h3><p class="diary-instructions">{{t.Detalle}}</p><p>{{dateLabel(t.Fecha)}} · {{t.Repeticion==='ninguna'?'Una vez':t.Repeticion}}</p><small>Avisar {{t.Anticipacion}} min antes · Repetir cada {{t.Frecuencia}} min</small><footer v-if="t.Estado==='pendiente'"><button type="button" :disabled="saving" @click="change(t,'concluir')">✓ Realizado</button><button type="button" :disabled="saving" @click="edit(t)">Editar</button><button type="button" :disabled="saving" @click="change(t,'cancelar')">Cancelar</button></footer></article><p v-if="!visible.length" class="diary-empty">No hay recordatorios en esta selección.</p></div>
 <b-modal modal-class="diary-modal-premium" v-model="modal" title="Recordatorio personal privado" hide-footer @hidden="stop"><form class="diary-form" @submit.prevent="save"><p v-if="formError" class="diary-error">{{formError}}</p><label>Título<input v-model="form.Titulo" required maxlength="180"><button type="button" @click="dictate('Titulo')">🎙 {{field==='Titulo'?'Detener':'Dictar título'}}</button></label><label>Detalle<textarea v-model="form.Detalle" rows="3" maxlength="5000"></textarea><button type="button" @click="dictate('Detalle')">🎙 {{field==='Detalle'?'Detener':'Dictar detalle'}}</button></label><label>Fecha y hora · Lima<input type="datetime-local" v-model="form.Fecha" required></label><label>Repetición<select v-model="form.Repeticion"><option value="ninguna">Una vez</option><option value="diaria">Diaria al completar</option><option value="semanal">Semanal al completar</option></select></label><div class="diary-form-grid"><label>Avisar antes (min)<input type="number" v-model.number="form.Anticipacion" min="0" max="1440" required></label><label>Repetir aviso (min)<input type="number" v-model.number="form.Frecuencia" min="1" max="1440" required></label></div><p v-if="field">Escuchando… {{interim}}</p><button type="submit" class="diary-primary" :disabled="saving || !!field">Guardar recordatorio</button></form></b-modal>
</section></template>
<script>
import config from '@/store/config';
import {limaInput,taskMillis} from '@/utils/diario';
export default {props:{context:{type:Object,required:true}},data(){return {items:[],limited:false,state:'pendiente',error:'',saving:false,modal:false,form:{},formError:'',field:'',interim:''}},computed:{visible(){return this.items.filter(t=>!this.state||t.Estado===this.state).sort((a,b)=>a.Fecha.localeCompare(b.Fecha))}},mounted(){this.load()},beforeDestroy(){this.stop()},methods:{
 async request(path,body){const r=await this.axios({url:config.API+'diario/personales'+path,method:body?'POST':'GET',data:body,headers:{'X-Diario-CSRF':this.context.csrf},timeout:15000});return r.data},
 message(e){return e.response&&e.response.data.error||'No se pudo guardar. Actualiza para comprobar el estado.'},
 dateLabel(v){return new Intl.DateTimeFormat('es-PE',{timeZone:'America/Lima',dateStyle:'short',timeStyle:'short'}).format(new Date(taskMillis(v)))},
 async load(){try{const r=await this.request('');this.items=r.recordatorios;this.limited=r.limitado;this.error=''}catch(e){this.error=this.message(e)}},
 create(){this.form={Titulo:'',Detalle:'',Fecha:limaInput(new Date(Date.now()+3600000)),Anticipacion:15,Frecuencia:15,Repeticion:'ninguna'};this.formError='';this.modal=true},edit(t){this.form=Object.assign({},t,{Fecha:t.Fecha.slice(0,16).replace(' ','T')});this.formError='';this.modal=true},
 async save(){if(this.saving)return;this.saving=true;try{await this.request(this.form.Id?'/'+this.form.Id:'',Object.assign({},this.form,{accion:'editar'}));this.modal=false;await this.load();this.$root.$emit('diario:changed')}catch(e){this.formError=this.message(e)}finally{this.saving=false}},
 async change(t,accion){if(this.saving)return;if(accion==='cancelar'&&!window.confirm('¿Cancelar tu recordatorio personal?'))return;this.saving=true;try{await this.request('/'+t.Id,{accion,Version:Number(t.Version)});await this.load();this.$root.$emit('diario:changed')}catch(e){this.error=this.message(e)}finally{this.saving=false}},
 stop(){if(this._speech){this._speech.onresult=null;this._speech.onend=null;this._speech.onerror=null;this._speech.abort();this._speech=null}this.field='';this.interim='';this.$root.$emit('diario:dictation',false)},
 dictate(field){if(this.field===field){this.stop();return}this.stop();const API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!API){this.formError='Puedes escribir: este navegador no admite dictado.';return}const speech=new API();this._speech=speech;this.field=field;this.$root.$emit('diario:dictation',true);speech.lang='es-PE';speech.continuous=true;speech.interimResults=true;speech.onresult=e=>{this.interim='';for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)this.form[field]=(this.form[field]+' '+e.results[i][0].transcript.trim()).trim().slice(0,field==='Titulo'?180:5000);else this.interim+=e.results[i][0].transcript};speech.onerror=()=>{this.formError='El dictado se detuvo. Revisa el permiso del micrófono o escribe el texto.';this.stop()};speech.onend=()=>this.stop();try{speech.start()}catch(e){this.formError='No se pudo activar el micrófono.';this.stop()}}
}};
</script>
<style>.diary-personal-head{display:flex;justify-content:space-between;gap:18px;align-items:center;margin:24px 0}.diary-personal-head h2{font-size:23px}.diary-personal>label{max-width:220px;margin-bottom:16px}.diary-personal-head p{color:#617b8d;font-size:13px}@media(max-width:700px){.diary-personal-head{flex-direction:column;align-items:flex-start}}</style>
